SELECT DISTINCT t0.ID, t0.VERSION, t1.ID, t1.CITY, t1.COUNTRY, t1.STREET, t1.ZIP, t1.CREATED_AT, t1.EMAIL, t1.FIRST_NAME, t1.LAST_NAME, t0.ORDER_DATE, t0.STATUS, t0.TOTAL, t2.ORDER_ID, t2.ID, t2.LINE_NO, t2.PRODUCT_ID, t2.QUANTITY, t2.UNIT_PRICE FROM ORDERS t0 INNER JOIN CUSTOMER t1 ON t0.CUSTOMER_ID = t1.ID INNER JOIN ORDER_LINE t2 ON t0.ID = t2.ORDER_ID WHERE (t0.ID >= ? AND t0.ID <= ?) ORDER BY t0.ID ASC, t2.ORDER_ID ASC;

